/* ---------- Status pill ---------- */
.dm-spl-stage{min-height:44px;justify-content:center}
.dm-spl-pill{background:var(--dm-surface);border-radius:var(--dm-r-pill);box-shadow:var(--dm-shadow);height:40px;display:flex;align-items:center;overflow:hidden;transition:width .6s var(--dm-ease),border-radius .5s var(--dm-ease),height .5s var(--dm-ease)}
.dm-spl-in{display:flex;align-items:center;gap:9px;padding:0 6px 0 14px;height:100%;white-space:nowrap;font-size:13.5px;transition:opacity .32s var(--dm-ease),filter .32s var(--dm-ease)}
.dm-spl-in.dm-out{opacity:0;filter:blur(4px);transition-duration:.16s}
/* the mark's box is the mark itself, so the room before it is the pill's own padding, the same as the room after the words
   (owner, 21 Nov: "too much on left vs right visually"): a pale dot no longer sits 5px further in than a spinner */
.dm-spl-in .dm-g{display:grid;place-items:center;min-width:6px;color:var(--dm-fg2)}
.dm-spl-in .dm-m{color:var(--dm-muted);font-variant-numeric:tabular-nums}
.dm-spl-in .dm-end{width:0}
.dm-spl-in>:is(.dm-g,.dm-m,.dm-fchip,.dm-pill){flex:none}
.dm-spl-in>span:not(.dm-g,.dm-m,.dm-end,.dm-fchip){min-width:0;overflow:hidden;text-overflow:ellipsis}
.dm-spl-in .dm-pill{height:28px;margin-left:var(--dm-s-1)}
/* nothing in it grows or shrinks when it is pressed (owner, 18 Nov) */
.dm-spl .dm-pill:active{transform:none}
/* the bar is a small card: its line and the track under it sit 16px in from every edge (owner, 18 Nov). Its line is as tall
   as its words, or as Review while Review is there, so it grows a little round the button and shrinks back after, smoothly,
   and keeps no room for it otherwise */
.dm-spl.dm-bar .dm-spl-pill{--dm-spl-row:18px;border-radius:var(--dm-r-card);height:calc(var(--dm-spl-row) + 45px);align-items:flex-start}
.dm-spl.dm-bar .dm-spl-pill:has(.dm-spl-in .dm-pill){--dm-spl-row:28px}
.dm-spl.dm-bar .dm-spl-in{height:var(--dm-spl-row);margin-top:16px;width:100%;padding:0 var(--dm-s-4);line-height:18px}
.dm-spl.dm-bar .dm-spl-in .dm-m,.dm-spl.dm-bar .dm-spl-in .dm-pill{margin-left:auto}
.dm-spl.dm-bar .dm-spl-in .dm-end{display:none}
.dm-spl-track{position:absolute;left:16px;right:16px;bottom:16px;height:3px;border-radius:var(--dm-r-tiny,2px);background:var(--dm-rail);overflow:hidden;opacity:0;transition:opacity .16s}
.dm-spl.dm-bar .dm-spl-track{opacity:1;transition:opacity .4s var(--dm-ease) .1s}
.dm-spl.dm-mo .dm-spl-track{opacity:0;transition:opacity .16s}
.dm-spl-fill{height:100%;width:0;border-radius:inherit;background:var(--dm-accent-mark,var(--dm-accent));transition:width .8s var(--dm-ease)}
.dm-spl-pill{position:relative}
/* Clean (owner, 17 Nov): a hairline pill, 36px, with the card's outline and short shadow; the marks keep their colours
   (the blue spinner and fill, the green tick, the orange wait dot). A step crosses with a 3px fade, no blur; Review is the
   ink button, round and concentric in the pill. The bar takes the card's round corners, its content 16px in from every edge
   (owner, 18 Nov), a 3px rail with the accent fill, and Review a 28px pill */
:root[data-style="clean"] .dm-spl-stage,:root [data-style="clean"] .dm-spl-stage,:root [data-style="clean"].dm-spl-stage{min-height:40px}
/* its hairline at half the card's (owner, 21 Nov: "reducing opacity on the border by 50% on clean") */
:root[data-style="clean"] .dm-spl-pill,:root [data-style="clean"] .dm-spl-pill,:root [data-style="clean"].dm-spl-pill{height:36px;border-radius:999px;background:var(--dm-surface);box-shadow:0 0 0 1px rgba(0,0,0,.035),0 1px 1px rgba(0,0,0,.04),0 2px 10px -4px rgba(0,0,0,.12);transition:width var(--dm-t) var(--dm-ease),border-radius .42s var(--dm-ease),height .42s var(--dm-ease)}
:root[data-style="clean"][data-theme="dark"] .dm-spl-pill,:root[data-theme="dark"] [data-style="clean"] .dm-spl-pill,:root[data-theme="dark"] [data-style="clean"].dm-spl-pill{box-shadow:0 0 0 1px rgba(255,255,255,.05),0 1px 1px rgba(0,0,0,.5),0 2px 10px -4px rgba(0,0,0,.6)}
@media (prefers-color-scheme:dark){:root[data-style="clean"]:not([data-theme="light"]) .dm-spl-pill,:root:not([data-theme="light"]) [data-style="clean"] .dm-spl-pill,:root:not([data-theme="light"]) [data-style="clean"].dm-spl-pill{box-shadow:0 0 0 1px rgba(255,255,255,.05),0 1px 1px rgba(0,0,0,.5),0 2px 10px -4px rgba(0,0,0,.6)}}
:root[data-style="clean"] .dm-spl-in,:root [data-style="clean"] .dm-spl-in,:root [data-style="clean"].dm-spl-in{gap:8px;padding:0 4px 0 13px;font-size:13px;color:var(--dm-fg);transition:opacity var(--dm-t-fast) var(--dm-ease),transform var(--dm-t-fast) var(--dm-ease)}
:root[data-style="clean"] .dm-spl-in.dm-out,:root [data-style="clean"] .dm-spl-in.dm-out,:root [data-style="clean"].dm-spl-in.dm-out{opacity:0;filter:none;transform:translateY(-3px);transition:opacity .15s ease-in-out,transform .15s ease-in-out}
:root[data-style="clean"] .dm-spl-in .dm-m,:root [data-style="clean"] .dm-spl-in .dm-m,:root [data-style="clean"].dm-spl-in .dm-m{color:var(--dm-muted)}
/* (Review is the site's small button, 28px, 4px in from the pill's edge all round) */
:root[data-style="clean"] .dm-spl-in .dm-pill,:root [data-style="clean"] .dm-spl-in .dm-pill,:root [data-style="clean"].dm-spl-in .dm-pill{height:28px;padding:0 12px;border-radius:999px;margin-left:2px}
:root[data-style="clean"] .dm-spl.dm-bar .dm-spl-pill,:root [data-style="clean"] .dm-spl.dm-bar .dm-spl-pill,:root [data-style="clean"].dm-spl.dm-bar .dm-spl-pill{height:calc(var(--dm-spl-row) + 45px);border-radius:var(--dm-r-card)}
:root[data-style="clean"] .dm-spl.dm-bar .dm-spl-in,:root [data-style="clean"] .dm-spl.dm-bar .dm-spl-in,:root [data-style="clean"].dm-spl.dm-bar .dm-spl-in{height:var(--dm-spl-row);padding:0 16px}
:root[data-style="clean"] .dm-spl.dm-bar .dm-spl-in .dm-pill,:root [data-style="clean"] .dm-spl.dm-bar .dm-spl-in .dm-pill,:root [data-style="clean"].dm-spl.dm-bar .dm-spl-in .dm-pill{height:28px;padding:0 12px;margin-left:auto}
/* the measure under the bar: it lets the pointer through */
:root[data-style="clean"] .dm-spl-track,:root [data-style="clean"] .dm-spl-track,:root [data-style="clean"].dm-spl-track{left:16px;right:16px;bottom:16px;height:3px;border-radius:var(--dm-r-tiny,2px);background:var(--dm-rail);pointer-events:none}
:root[data-style="clean"] .dm-spl-fill,:root [data-style="clean"] .dm-spl-fill,:root [data-style="clean"].dm-spl-fill{background:var(--dm-accent-mark);transition:width .6s var(--dm-ease)}
@media (prefers-reduced-motion:reduce){:root[data-style="clean"] :is(.dm-spl-pill,.dm-spl-in,.dm-spl-in.dm-out,.dm-spl-fill),:root [data-style="clean"] :is(.dm-spl-pill,.dm-spl-in,.dm-spl-in.dm-out,.dm-spl-fill),:root [data-style="clean"]:is(.dm-spl-pill,.dm-spl-in,.dm-spl-in.dm-out,.dm-spl-fill){transition:none!important}}
